command:
set -eu
if ! id nodeapp >/dev/null 2>&1; then useradd --create-home --shell /usr/sbin/nologin nodeapp; fi
uid=$(id -u nodeapp)
install -d -o nodeapp -g nodeapp /home/nodeapp/node-hello /home/nodeapp/.config/systemd/user
cat > /home/nodeapp/node-hello/app.js <<'ANTRIEB_APP'
'use strict';
const http = require('http');
const body = 'Hello, world!';
const server = http.createServer((req, res) => {
  if (req.url === '/') {
    res.writeHead(200, {'Content-Type': 'text/plain', 'Content-Length': Buffer.byteLength(body)});
    res.end(body);
  } else {
    res.writeHead(404, {'Content-Type': 'text/plain'});
    res.end('Not found');
  }
});
server.listen(8080, '0.0.0.0');
ANTRIEB_APP
cat > /home/nodeapp/node-hello/Containerfile <<'ANTRIEB_CONTAINER'
FROM docker.io/library/node:22-alpine
WORKDIR /app
COPY --chown=node:node app.js /app/app.js
USER node
EXPOSE 8080
CMD ["node", "/app/app.js"]
ANTRIEB_CONTAINER
chown -R nodeapp:nodeapp /home/nodeapp/node-hello /home/nodeapp/.config
restorecon -RF /home/nodeapp >/dev/null 2>&1 || true
printf 'uid=%s\n' "$uid"
printf 'subuid='; grep '^nodeapp:' /etc/subuid || true
printf 'subgid='; grep '^nodeapp:' /etc/subgid || true
printf 'shell='; getent passwd nodeapp | cut -d: -f7

